import type {Extension, Transform} from 'mdast-util-from-markdown'
import {visit} from 'unist-util-visit'

/** A simple mdast extension that adds some data to table cells to make them easier to render. */
export function mdastEnrichTables(): Extension {
  return {
    transforms: [enrichTableCells],
  }
}

declare module 'mdast' {
  interface TableCellData {
    /** Indicates whether a table cell should render as a `th` instead of a `td` element. */
    isHeader?: boolean
    /** The text alignment direction of this table cell. */
    alignment?: AlignType
  }
}

const enrichTableCells: Transform = function (tree) {
  visit(tree, 'table', table => {
    for (const [rowIndex, row] of table.children.filter(n => n.type === 'tableRow').entries())
      for (const [cellIndex, cell] of row.children.filter(n => n.type === 'tableCell').entries()) {
        cell.data ??= {}
        cell.data.isHeader = rowIndex === 0
        cell.data.alignment = table.align?.[cellIndex]
      }
  })
}
