import safeStorage from '@github-ui/safe-storage'

// Key prefix for favorite label storage
const FAVORITE_LABELS_STORAGE_PREFIX = 'favorite-labels'

// Storage configuration with 30 days TTL
const safeLocalStorage = safeStorage('localStorage', {
  throwQuotaErrorsOnSet: false,
  ttl: 1000 * 60 * 60 * 24 * 30, // 30 days
})

/**
 * Represents a stored favorite label entry
 */
interface FavoriteLabelEntry {
  /** The label ID */
  readonly labelId: string
  /** Number of times this label has been used */
  readonly count: number
  /** Last time this label was used (timestamp) */
  readonly lastUsed: number
}

/**
 * Favorite labels storage per repository
 */
interface FavoriteLabelsStorage {
  /** Map of label ID to label entry */
  readonly labels: Record<string, FavoriteLabelEntry>
}

/**
 * Creates a storage key for a specific repository
 */
function createStorageKey(repoNwo: string): string {
  return `${FAVORITE_LABELS_STORAGE_PREFIX}:${repoNwo}`
}

/**
 * Gets the favorite labels storage for a specific repository
 */
function getFavoriteLabelsStorage(repoNwo: string): FavoriteLabelsStorage {
  const key = createStorageKey(repoNwo)
  const stored = safeLocalStorage.getItem(key)

  if (!stored) {
    return {labels: {}}
  }

  try {
    const parsed = JSON.parse(stored) as FavoriteLabelsStorage
    return parsed
  } catch {
    // If parsing fails, return empty storage
    return {labels: {}}
  }
}

/**
 * Saves favorite labels storage for a specific repository
 */
function saveFavoriteLabelsStorage(repoNwo: string, storage: FavoriteLabelsStorage): void {
  const key = createStorageKey(repoNwo)
  try {
    safeLocalStorage.setItem(key, JSON.stringify(storage))
  } catch {
    // Silently fail if storage is unavailable
  }
}

/**
 * Records usage for multiple labels
 */
export function recordLabelsUsage(repoNwo: string, labelIds: string[]): void {
  if (labelIds.length === 0) return

  const storage = getFavoriteLabelsStorage(repoNwo)
  const now = Date.now()

  for (const labelId of labelIds) {
    const existingEntry = storage.labels[labelId]
    storage.labels[labelId] = {
      labelId,
      count: existingEntry ? existingEntry.count + 1 : 1,
      lastUsed: now,
    }
  }

  saveFavoriteLabelsStorage(repoNwo, storage)
}

/**
 * Gets the most frequently used labels for a repository
 */
export function getMostUsedLabels(repoNwo: string, days = 10, limit = 4): FavoriteLabelEntry[] {
  const storage = getFavoriteLabelsStorage(repoNwo)
  const now = Date.now()
  const cutoff = now - days * 24 * 60 * 60 * 1000

  return Object.values(storage.labels)
    .filter(entry => entry.lastUsed >= cutoff)
    .sort((a, b) => {
      // Sort by count descending, then by last used descending
      if (a.count !== b.count) {
        return b.count - a.count
      }
      return b.lastUsed - a.lastUsed
    })
    .slice(0, limit)
}
